use std::sync::Arc;

use super::{Analyzer, BlockDecoder, BlockKind, Extractor, FormatSpec};

/// The set of extractors, block decoders and analyzers an engine uses.
///
/// [`Registry::builtin`] holds everything compiled into this build of whiff
/// (generated by `build.rs`); add extractors from other crates with
/// [`Registry::with`]. Embedders who want exact control start from
/// [`Registry::empty`].
#[derive(Clone, Default)]
pub struct Registry {
    extractors: Vec<Arc<dyn Extractor>>,
    decoders: Vec<Arc<dyn BlockDecoder>>,
    analyzers: Vec<Arc<dyn Analyzer>>,
}

impl std::fmt::Debug for Registry {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Registry")
            .field("extractors", &self.extractors.iter().map(|e| e.meta().id).collect::<Vec<_>>())
            .field("decoders", &self.decoders.iter().map(|d| d.id()).collect::<Vec<_>>())
            .field("analyzers", &self.analyzers.iter().map(|a| a.id()).collect::<Vec<_>>())
            .finish()
    }
}

struct StaticExtractor(&'static dyn Extractor);
impl Extractor for StaticExtractor {
    fn meta(&self) -> &'static super::ExtractorMeta {
        self.0.meta()
    }
    fn sniff(&self, probe: &super::Probe<'_>) -> Option<super::Sniff> {
        self.0.sniff(probe)
    }
    fn extract(&self, src: &mut dyn super::Source, cx: &mut super::Context<'_>) -> Result<(), super::ExtractError> {
        self.0.extract(src, cx)
    }
}

struct StaticDecoder(&'static dyn BlockDecoder);
impl BlockDecoder for StaticDecoder {
    fn kind(&self) -> BlockKind {
        self.0.kind()
    }
    fn id(&self) -> &'static str {
        self.0.id()
    }
    fn version(&self) -> u32 {
        self.0.version()
    }
    fn decode(&self, data: &[u8], cx: &mut super::Context<'_>) -> Result<(), super::ExtractError> {
        self.0.decode(data, cx)
    }
}

struct StaticAnalyzer(&'static dyn Analyzer);
impl Analyzer for StaticAnalyzer {
    fn id(&self) -> &'static str {
        self.0.id()
    }
    fn version(&self) -> u32 {
        self.0.version()
    }
    fn stage(&self) -> super::AnalyzerStage {
        self.0.stage()
    }
    fn run(
        &self,
        report: &mut super::Report,
        text: &super::TextStore,
        options: &super::Options,
    ) -> Result<(), super::ExtractError> {
        self.0.run(report, text, options)
    }
}

impl Registry {
    /// Nothing registered.
    pub fn empty() -> Self {
        Self::default()
    }

    /// Every extractor, block decoder and analyzer compiled into this build
    /// (enabled features).
    pub fn builtin() -> Self {
        let mut r = Self::builtin_analyzers();
        for e in crate::builtin::extractors() {
            r.push_extractor(Arc::new(StaticExtractor(e)));
        }
        for d in crate::builtin::block_decoders() {
            r.push_decoder(Arc::new(StaticDecoder(d)));
        }
        r.sort();
        r
    }

    /// The built-in analyzers only (no extractors or decoders).
    pub fn builtin_analyzers() -> Self {
        let mut r = Self::empty();
        for a in crate::builtin::analyzers() {
            r.push_analyzer(Arc::new(StaticAnalyzer(a)));
        }
        r.sort();
        r
    }

    /// Add an extractor (ignored if one with the same id exists).
    #[must_use]
    pub fn with(mut self, extractor: impl Extractor) -> Self {
        self.push_extractor(Arc::new(extractor));
        self.sort();
        self
    }

    /// Add a block decoder (ignored if one with the same id exists).
    #[must_use]
    pub fn with_block_decoder(mut self, decoder: impl BlockDecoder) -> Self {
        self.push_decoder(Arc::new(decoder));
        self.sort();
        self
    }

    /// Add an analyzer (ignored if one with the same id exists).
    #[must_use]
    pub fn with_analyzer(mut self, analyzer: impl Analyzer) -> Self {
        self.push_analyzer(Arc::new(analyzer));
        self.sort();
        self
    }

    /// Keep only extractors whose id satisfies `keep` (decoders and analyzers stay).
    #[must_use]
    pub fn retain_extractors(mut self, keep: impl Fn(&str) -> bool) -> Self {
        self.extractors.retain(|e| keep(e.meta().id));
        self
    }

    fn push_extractor(&mut self, e: Arc<dyn Extractor>) {
        if !self.extractors.iter().any(|x| x.meta().id == e.meta().id) {
            self.extractors.push(e);
        }
    }

    fn push_decoder(&mut self, d: Arc<dyn BlockDecoder>) {
        if !self.decoders.iter().any(|x| x.id() == d.id()) {
            self.decoders.push(d);
        }
    }

    fn push_analyzer(&mut self, a: Arc<dyn Analyzer>) {
        if !self.analyzers.iter().any(|x| x.id() == a.id()) {
            self.analyzers.push(a);
        }
    }

    fn sort(&mut self) {
        self.extractors
            .sort_by(|a, b| b.meta().priority.cmp(&a.meta().priority).then_with(|| a.meta().id.cmp(b.meta().id)));
        self.decoders.sort_by_key(|d| d.id());
        self.analyzers.sort_by(|a, b| a.stage().cmp(&b.stage()).then_with(|| a.id().cmp(b.id())));
    }

    /// Extractors, highest priority first.
    pub fn extractors(&self) -> impl Iterator<Item = &dyn Extractor> {
        self.extractors.iter().map(AsRef::as_ref)
    }

    /// Extractor by id.
    pub fn extractor(&self, id: &str) -> Option<&dyn Extractor> {
        self.extractors().find(|e| e.meta().id == id)
    }

    /// Every declared format with the extractor declaring it.
    pub fn formats(&self) -> impl Iterator<Item = (&'static FormatSpec, &dyn Extractor)> {
        self.extractors().flat_map(|e| e.meta().formats.iter().map(move |f| (f, e)))
    }

    /// Extractors handling `format_id`, highest priority first.
    pub fn extractors_for<'a>(&'a self, format_id: &'a str) -> impl Iterator<Item = &'a dyn Extractor> + 'a {
        self.extractors().filter(move |e| e.meta().formats.iter().any(|f| f.id == format_id))
    }

    /// Block decoders.
    pub fn block_decoders(&self) -> impl Iterator<Item = &dyn BlockDecoder> {
        self.decoders.iter().map(AsRef::as_ref)
    }

    /// The decoder for `kind`, if any.
    pub fn block_decoder(&self, kind: BlockKind) -> Option<&dyn BlockDecoder> {
        self.block_decoders().find(|d| d.kind() == kind)
    }

    /// Analyzers in run order.
    pub fn analyzers(&self) -> impl Iterator<Item = &dyn Analyzer> {
        self.analyzers.iter().map(AsRef::as_ref)
    }
}
